async function skipVerdict(userId, s, job, collected, clientCountry, manual) {
  const { data: mine } = await createAdminClient().from("user_jobs").select("applied_at").eq("user_id", userId).eq("job_id", job.id).maybeSingle();
  if (mine?.applied_at) {
    return { skipped: true, hard: false, already_applied: true, message: "You've already applied to this project \u2014 not regenerating." };
  }
  const skip = skipReason(s, job, clientCountry, collected);
  if (skip) return { skipped: true, hard: true, message: `Skipped \u2014 matches the filters (${skip}); no proposal generated.` };
  if (manual) return null;
  const personal = userFilterReason(s, job);
  if (personal) return { skipped: true, hard: false, message: `Skipped \u2014 hidden by your own filters (${personal}); no proposal generated. Press \u2728 Generate to write one anyway.` };
  const bad = await badMark(job.id);
  if (bad) return { skipped: true, hard: false, message: `Skipped \u2014 ${bad}; no proposal generated. Press \u2728 Generate to write one anyway.` };
  return null;
}
async function generateForUser(userId, ref, clientCountry, opts = {}) {
  const s = await getEffectiveSettings(userId);
  const { job, collected, error } = await ensureJob(s, ref);
  if (error || !job) return error;
  if (!opts.force) {
    const verdict = await skipVerdict(userId, s, job, collected, clientCountry, Boolean(opts.manual));
    if (verdict) {
      await touchUserJob(userId, job.id, {});
      return { status: 200, body: { ok: false, ...verdict } };
    }
  }
  if (!s.OPENAI_API_KEY) {
    return { status: 400, body: { ok: false, message: "No OpenAI API key is set \u2014 ask the admin to add one in Admin \u203A Settings." } };
  }
  const pricing = resolvePricing(s, job);
  let proposal;
  try {
    proposal = await generateProposal(s.OPENAI_API_KEY, s.OPENAI_MODEL || "gpt-5.2-mini", {
      title: job.title,
      description: job.description ?? "",
      skills: job.skills ?? "",
      budgetMin: job.budget_min,
      budgetMax: job.budget_max,
      currency: job.currency,
      profileBullets: lines(s.BOT_PROFILE_BULLETS),
      portfolioUrls: portfolio(s.BOT_PORTFOLIO_URLS),
      signatureName: (s.BOT_SIGNATURE_NAME ?? "").trim(),
      extraInstructions: s.BOT_PROPOSAL_INSTRUCTIONS ?? "",
      includeName: isTrue(s.BOT_INCLUDE_NAME),
      includeProfile: isTrue(s.BOT_INCLUDE_PROFILE),
      askQuestion: isTrue(s.BOT_ASK_QUESTION),
      template: s.BOT_PROPOSAL_TEMPLATE ?? "",
      prefix: s.BOT_PROPOSAL_PREFIX ?? "",
      suffix: s.BOT_PROPOSAL_SUFFIX ?? "",
      prefixInline: isTrue(s.BOT_PROPOSAL_PREFIX_INLINE)
    });
  } catch (e) {
    const err = e;
    return { status: 400, body: { ok: false, message: `OpenAI generation failed: ${err.name}: ${String(err.message).slice(0, 200)}` } };
  }
  const [amount, period] = await pricing;
  await touchUserJob(userId, job.id, {
    proposal,
    amount,
    period_days: period,
    generated_at: (/* @__PURE__ */ new Date()).toISOString()
  });
  return {
    status: 200,
    body: {
      ok: true,
      id: job.id,
      proposal,
      amount,
      period,
      currency: job.currency ?? "",
      milestone: int(s.BOT_DEFAULT_MILESTONE_PERCENT, 50),
      seal: isTrue(s.BOT_SEAL_BIDS),
      autogen: isTrue(s.BOT_AUTO_GENERATE),
      autobid: isTrue(s.BOT_AUTO_BID)
    }
  };
}

// ../supabase/generate-src/entry.ts
var json = (status, body) => new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json" } });
Deno.serve(async (req) => {
  try {
    const userId = await userFromApiKey(req);
    if (!userId) {
      return json(401, { ok: false, message: "Missing or invalid API key. Open your bot Settings page, create a key, then set it from the Tampermonkey menu \u2192 \u201CSet bot API key\u201D." });
    }
    const q = new URL(req.url).searchParams;
    const idRaw = (q.get("id") ?? "").trim();
    const seo = (q.get("seo") ?? "").trim() || null;
    if (idRaw && !/^\d+$/.test(idRaw)) return json(400, { ok: false, message: "Bad project id." });
    const ref = { id: idRaw ? Number(idRaw) : null, seo };
    if (!ref.id && !ref.seo) return json(400, { ok: false, message: "Missing project id or seo." });
    const r = await generateForUser(userId, ref, (q.get("country") ?? "").trim() || null, { manual: q.get("manual") === "1" });
    return json(r.status, r.body);
  } catch (e) {
    return json(500, { ok: false, message: `Generate failed: ${String(e.message ?? e).slice(0, 200)}` });
  }
});
